<?php require_once '../includes/functions.php';require_login();$s=$pdo->prepare('SELECT r.*,p.name FROM reviews r JOIN places p ON p.id=r.place_id WHERE r.user_id=? ORDER BY r.created_at DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();$page_title='My Reviews';require '../includes/header.php';?><section class="section"><h1>My Reviews</h1><?php foreach($rows as $r):?><div class="review"><b><?=e($r['name'])?> · ★ <?=$r['rating']?>/5</b><span class="status-pill"><?=e($r['status'])?></span><p><?=e($r['comment'])?></p></div><?php endforeach;?><?php if(!$rows):?><div class="empty-state">You haven't written any reviews.</div><?php endif;?></section><?php require '../includes/footer.php';?>
